test("findCargoPackageDir stops at [package], not workspace", () => {
	const cwd = tempDir();
	try {
		writeFileSync(join(cwd, "Cargo.toml"), '[workspace]\nmembers = ["crate"]\n');
		mkdirSync(join(cwd, "crate", "src"), { recursive: true });
		writeFileSync(join(cwd, "crate", "Cargo.toml"), '[package]\nname = "crate"\nversion = "0.1.0"\n');
		writeFileSync(join(cwd, "crate", "src", "lib.rs"), "");
		expect(hasPackageTable("[workspace.package]\n")).toBe(false);
		expect(findCargoPackageDir(join(cwd, "crate", "src", "lib.rs"))).toBe(join(cwd, "crate"));
		expect(findCargoPackageDir(join(cwd, "Cargo.toml"))).toBe(undefined);
	} finally {
		rmSync(cwd, { recursive: true, force: true });
	}
});

test("findCargoPackageDir skips a template crate instead of climbing to the crate around it", () => {
	const cwd = tempDir();
	try {
		const template = join(cwd, "projects", "stack", "apps", "server");
		writeFileSync(join(cwd, "Cargo.toml"), '[package]\nname = "host"\nversion = "0.1.0"\n');
		mkdirSync(join(template, "src"), { recursive: true });
		writeFileSync(join(template, "Cargo.toml"), '[package]\nname = "{{CARGO_PACKAGE_NAME}}"\nversion = "0.1.0"\n');
		writeFileSync(join(template, "src", "lib.rs"), "");
		expect(findCargoPackageDir(join(template, "src", "lib.rs"))).toBe(undefined);
		expect(findCargoPackageDir(join(cwd, "src", "lib.rs"))).toBe(cwd);
	} finally {
		rmSync(cwd, { recursive: true, force: true });
	}
});

